import React, { useRef } from "react";
import { useNavigate } from 'react-router-dom';

import Navbar from "./navbar";
import './teacherlogin.css';

function Teacherlogin1() {
  const inputref1 = useRef(); // username
  const inputref2 = useRef(); // password
  const navigate = useNavigate();

  const login1 = (id, password) => {
    if (id === "" || password === "") {
      alert("Enter both ID and password");
    } else {
      if (id === "admin" && password === "admin@423") {
        navigate('/teacherdashboard');
      } else {
        alert("Wrong username or password");
      }
    }
  };

  return (
    <>
      <div>
        <Navbar />
        <div>
          <h2>Teacher login</h2>
          <br />
          <div className="input">
            <div className='arrange'>
              <label className="my-label">UserName</label>
              <br />
              <input
                type="text"
                placeholder="Enter UserName"
                className="my-input"
                ref={inputref1}
              />
            </div>

            <div className='arrange'>
              <label className="my-label">Password</label>
              <br />
              <input
                type="password"
                placeholder="Enter Password"
                className="my-input"
                ref={inputref2}
              />
            </div>
          </div>

          <div className="buttondiv">
            <button onClick={() => login1(inputref1.current.value, inputref2.current.value)}>
              Login
            </button>
          </div>
        </div>
      </div>
    </>
  );
}

export default Teacherlogin1;
